import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createGenerationHarness} from './test/helpers/generation-harness.mjs';
import {regionFixture} from './test/helpers/region-fixture.mjs';
import {terrainDefault,terrainRisk,validateClassification} from './src/classification.ts';
const cases=[];
const check=(id,actual,expected)=>{assert.deepEqual(actual,expected,id);cases.push({id,actual,expected,status:'passed'});};
const h=createGenerationHarness(42);h.render();const alerts=[];h.setWindow({alert:m=>alerts.push(m),confirm:()=>true});h.injectFunction('readTextFile',async f=>f.text);
const fixture=regionFixture();fixture.map.biomeOverrideByHexKey={'2,0':'plain_mixed_forest'};delete fixture.map.knave;delete fixture.map.classification;
await h.render().handleImportJson({target:{files:[{text:JSON.stringify(fixture)}],value:'x'}});check('import_fixture',alerts,[]);h.guardRandom();
const snap=()=>{const d=JSON.parse(JSON.stringify(h.render().createSaveData()));delete d.savedAt;return d;};
const before=snap(),key='2,0';
const edit=value=>{h.render().setEditMode(true);h.render();check('draft_'+value,h.render().changeKnaveDraft({difficulty:value}),true);h.render();check('commit_'+value,h.render().finishKnaveDraft(),true);h.render();};
const walk=n=>!n||typeof n!=='object'?[]:Array.isArray(n)?n.flatMap(walk):n.props?[...(Object.hasOwn(n.props,'data-terrain-classification')?[n]:[]),...walk(n.props.children)]:[];
const visible=()=>{h.render().setEditMode(false);return walk(h.render().knavePanel).length;};
check('forest_default',terrainDefault('plain_mixed_forest'),'difficult');
edit('dangerous');const dangerous=snap();check('dangerous_saved',dangerous.map.classification.difficultyByHex[key],'dangerous');check('region_preserved',dangerous.map.regions,before.map.regions);check('biome_preserved',dangerous.map.biomeOverrideByHexKey,before.map.biomeOverrideByHexKey);check('notes_preserved',dangerous.map.gmNotesByHexKey,before.map.gmNotesByHexKey);check('rng_preserved',dangerous.generation,before.generation);check('dangerous_visible',visible(),1);
h.render().undoMap();check('undo_exact',snap(),before);h.render().redoMap();check('redo_exact',snap(),dangerous);
await h.render().handleImportJson({target:{files:[{text:JSON.stringify(dangerous)}],value:'x'}});check('reload_exact',snap(),dangerous);
edit('normal');check('normal_hidden',visible(),0);check('normal_manual_override',snap().map.classification.difficultyByHex[key],'normal');
edit('unknown');check('unknown_saved',snap().map.classification.difficultyByHex[key],'unknown');check('unknown_hides_default',visible(),0);
edit('difficult');check('difficult_visible',visible(),1);
edit('auto');check('auto_removes_layer',snap().map.classification,undefined);check('auto_restores_forest_default',visible(),1);check('auto_no_geometry_change',snap().map.regions,before.map.regions);
check('mountain_default',terrainDefault('mountains'),'dangerous');check('mountain_risk',terrainRisk('mountains','en'),'risk of falling');check('swamp_risk',terrainRisk('swamp','en'),'risk of becoming mired');check('future_biome_unknown',terrainDefault('future_biome'),'unknown');
let rejected=false;try{validateClassification({version:1,difficultyByHex:{[key]:'dangerous'},discoveryByPoi:{},hazardByHex:{[key]:{type:'freezing',source:'p21'}}},{hexes:new Set([key]),pois:new Set()},14);}catch{rejected=true;}check('typed_hazard_not_part_of_classification_schema',rejected,true);
edit('dangerous');visible();check('adaptation_start',h.render().startDetailAdaptation(),true);check('adaptation_apply',h.render().applyDetailAdaptation(),true);const detailed=snap();check('detail_save_v14',detailed.version,14);check('detail_preserves_classification',detailed.map.classification.difficultyByHex[key],'dangerous');
await h.render().handleImportJson({target:{files:[{text:JSON.stringify(detailed)}],value:'x'}});check('v14_reload_preserves_classification',snap().map.classification,detailed.map.classification);check('no_alerts',alerts,[]);
const brief=cases.map(x=>({...x,actual:typeof x.actual==='object'?'deep equality checked':x.actual,expected:typeof x.expected==='object'?'deep equality checked':x.expected}));
const out={code_sha:'9ca7dc6d5839ed897ccb784ae29d4029a5e76590',harness:'Existing real App callbacks with React hooks mocked; no DOM browser',status:'passed',case_count:cases.length,cases:brief};fs.writeFileSync('probe-results.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out));
